// Some portions generated by Claude
'use strict';

// Saved query results share one dynamic budget (ExecPlan .agent/execplan-query-tabs-g2.md, Part 2, M4): a result
// may use all of it until another needs room; then the least recently shown results are trimmed, each only as much
// as needed and not below 10,000 rows while trimming others can make room, and orphans go first.

const test = require('node:test');
const assert = require('node:assert/strict');
const { loadApi } = require('./query-load-more-harness.js');
const { fakeIndexedDB, realWorkerFactory } = require('./row-store-worker-harness.js');

const REGISTRY = 'rdf4j.workbench.row-store.v2:';
const DATABASE = 'rdf4j-workbench-row-store:';

function plain(value) {
    return JSON.parse(JSON.stringify(value));
}

test('trimming takes the least recently shown result first, only as much as needed, down to the floor', () => {
    const { api } = loadApi();
    const stores = [
        { id: 'new', rows: 50000, bytes: 50000, recency: 30 },
        { id: 'old', rows: 30000, bytes: 30000, recency: 10 },
        { id: 'mid', rows: 20000, bytes: 20000, recency: 20 }
    ];
    assert.deepEqual(plain(api.planTrim(stores, 5000, 10000)), {
        steps: [{ id: 'old', rows: 30000, keep: 25000, freed: 5000 }], freed: 5000, enough: true
    }, 'one result is trimmed, by exactly what is needed');
    assert.deepEqual(plain(api.planTrim(stores, 35000, 10000)), {
        steps: [{ id: 'old', rows: 30000, keep: 10000, freed: 20000 },
            { id: 'mid', rows: 20000, keep: 10000, freed: 10000 },
            { id: 'new', rows: 50000, keep: 45000, freed: 5000 }],
        freed: 35000, enough: true
    }, 'the next one is trimmed once a result reaches the floor, so every result keeps 10,000 rows');
    const deep = plain(api.planTrim(stores, 80000, 10000));
    assert.deepEqual(deep.steps.map(step => [step.id, step.keep]), [['old', 0], ['mid', 10000], ['new', 10000]],
        'below the floor only when that is not enough, the least recent first');
    assert.equal(deep.enough, true);
    const all = plain(api.planTrim(stores, 200000, 10000));
    assert.equal(all.enough, false, 'it says when even deleting everything is not enough');
    assert.equal(all.freed, 100000);
});

test('for a full browser storage, results are deleted whole, the least recently shown first', () => {
    const { api } = loadApi();
    const plan = plain(api.planTrim([
        { id: 'new', rows: 50000, bytes: 50000, recency: 30 },
        { id: 'old', rows: 30000, bytes: 30000, recency: 10 }
    ], 1000, 10000, true));
    assert.deepEqual(plan.steps.map(step => [step.id, step.keep]), [['old', 0]]);
});

test('orphans go first, whole; results already at the floor are left until the others are', () => {
    const { api } = loadApi();
    const plan = plain(api.planTrim([
        { id: 'small', rows: 8000, bytes: 8000, recency: 1 },
        { id: 'orphan', rows: 0, bytes: 3000, recency: 50, orphan: true },
        { id: 'big', rows: 40000, bytes: 80000, recency: 40 }
    ], 7000, 10000));
    assert.deepEqual(plan.steps, [
        { id: 'orphan', rows: 0, keep: 0, freed: 3000 },
        { id: 'big', rows: 40000, keep: 38000, freed: 4000 }
    ]);
});

test('the budget is half of 80 % of the quota, capped, and 2 GB where the browser gives no estimate', async () => {
    const first = loadApi();
    first.context.navigator = { storage: { estimate: async () => ({ quota: 10 * 1000 * 1000 * 1000, usage: 9e9 }) } };
    assert.equal(await first.api.rowStoreBudget(), 4 * 1000 * 1000 * 1000, 'the usage the browser reports is not used');
    const capped = loadApi();
    capped.context.navigator = { storage: { estimate: async () => ({ quota: 1e15 }) } };
    assert.equal(await capped.api.rowStoreBudget(), capped.api.ROW_STORE_CAP_BYTES);
    const none = loadApi();
    assert.equal(await none.api.rowStoreBudget(), 2 * 1024 * 1024 * 1024);
    none.api.setRowStoreBudget(1234);
    assert.equal(await none.api.rowStoreBudget(), 1234, 'tests set the budget');
});

function mapStorage() {
    const values = new Map();
    return {
        values,
        get length() { return values.size; },
        key(index) { return [...values.keys()][index] || null; },
        getItem(key) { return values.has(key) ? values.get(key) : null; },
        setItem(key, value) { values.set(key, String(value)); },
        removeItem(key) { values.delete(key); }
    };
}

function rows(from, to) {
    return Array.from({ length: to - from }, (_, index) => [{ kind: 'literal', value: 'r' + (from + index) }]);
}

async function settle(rounds = 40) {
    for (let count = 0; count < rounds; count++) await new Promise(resolve => setImmediate(resolve));
}

/** A saved store of `count` rows kept for a tab, shown at `shownAt`, and let go by its page. */
async function savedStore(page, count, tabId, shownAt) {
    const store = await page.api.createRowStore(page.options);
    await store.append(rows(0, count));
    const saved = await store.persist();
    store.retain({ scope: 's', tabId, owner: 'page-x', shownAt, rows: count });
    await store.release();
    return saved;
}

function entryOf(localStorage, id) {
    const value = localStorage.getItem(REGISTRY + id);
    return value === null ? null : JSON.parse(value);
}

test('making room trims the stores no page has open, deletes orphans, and leaves open ones alone', async () => {
    const storage = fakeIndexedDB();
    const localStorage = mapStorage();
    const page = loadApi({ localStorage });
    page.options = { workerFactory: realWorkerFactory(storage).factory, storageTimeout: 2000 };
    page.api.setRowStoreBudget(1e12);
    const old = await savedStore(page, 6, 't-old', 10);
    const recent = await savedStore(page, 6, 't-recent', 30);
    const orphan = await savedStore(page, 3, 't-orphan', 50);
    const open = await page.api.openRowStore(await savedStore(page, 6, 't-open', 1), page.options);
    const perRow = old.bytes / 6;
    const referenced = () => ({ [old.id]: true, [recent.id]: true, [open.id]: true });

    const freed = await page.api.makeRoom(Math.round(orphan.bytes + 5 * perRow), {
        indexedDB: storage.indexedDB, locks: undefined, storage: localStorage, referenced, floor: 2,
        rowStoreOptions: page.options, document: { visibilityState: 'visible' }
    });
    assert.ok(freed >= orphan.bytes + 4 * perRow);
    assert.equal(entryOf(localStorage, orphan.id), null, 'the orphan is deleted whole');
    assert.ok(!storage.databases.has(DATABASE + orphan.id));
    assert.equal(entryOf(localStorage, old.id).retained.rows, 2, 'the least recently shown is trimmed to the floor');
    const recentRows = entryOf(localStorage, recent.id).retained.rows;
    assert.ok(recentRows === 4 || recentRows === 5, 'then the next, by what is still needed: ' + recentRows);
    assert.equal(await open.count(), 6, 'a store this page has open is never trimmed');

    const later = loadApi({ localStorage });
    const reopened = await later.api.openRowStore(old, page.options);
    assert.equal(await reopened.count(), 2);
    assert.deepEqual(Array.from(await reopened.read(0, 5), row => row[0].value), ['r0', 'r1'], 'the first rows stay');
    await reopened.release();
    await open.release();
});

test('a growing result over the budget makes room by trimming the others', async () => {
    const storage = fakeIndexedDB();
    const localStorage = mapStorage();
    const page = loadApi({ localStorage });
    page.options = { workerFactory: realWorkerFactory(storage).factory, storageTimeout: 2000, spillRowLimit: 0 };
    page.api.setRowStoreBudget(1e12);
    const old = await savedStore(page, 20, 't-old', 10);
    const perRow = old.bytes / 20;
    page.api.setRowStoreBudget(Math.round(old.bytes + 10 * perRow));
    const growing = await page.api.createRowStore(page.options);
    await growing.append(rows(0, 15));
    // The registry records the store's size at most once a second.
    await new Promise((resolve) => setTimeout(resolve, 1200));
    await settle(200);
    const trimmed = entryOf(localStorage, old.id).retained.rows;
    assert.ok(trimmed < 20, 'the saved result was trimmed for the growing one, to ' + trimmed);
    assert.equal(await growing.count(), 15);
    await growing.dispose();
});

const { MemoryWorker } = require('./query-load-more-harness.js');

/** Browser storage that refuses the next `refusals` appends as full. */
class FullWorker extends MemoryWorker {
    constructor(state) {
        super();
        this.state = state;
    }
    postMessage(message) {
        if (message.op === 'append' && this.state.refusals > 0) {
            this.state.refusals -= 1;
            this.messages.push(message);
            queueMicrotask(() => {
                const response = { requestId: message.requestId, ok: false, error: 'QuotaExceededError: full',
                    errorName: 'QuotaExceededError' };
                for (const callback of this.listeners.get('message') || []) callback({ data: response });
            });
            return;
        }
        super.postMessage(message);
    }
}

test('a write that does not fit is tried again after deleting saved results; when that is not enough the rows written are kept',
    async () => {
        const localStorage = mapStorage();
        const storage = fakeIndexedDB();
        storage.databases.set(DATABASE + 'rows-1-old', new Map());
        const page = loadApi({ localStorage, indexedDB: storage.indexedDB });
        const state = { refusals: 1 };
        const options = { workerFactory: () => new FullWorker(state), spillRowLimit: 0, storageTimeout: 2000 };
        localStorage.setItem(REGISTRY + 'rows-1-old', JSON.stringify({ created: 1, used: 1, bytes: 40000,
            retained: { scope: 's', tabId: 't', owner: 'p', shownAt: 1, rows: 20000 } }));
        const store = await page.api.createRowStore(options);
        await store.append(rows(0, 3));
        await settle(200);
        assert.equal(entryOf(localStorage, 'rows-1-old'), null, 'a saved result was deleted for room');
        assert.ok(!storage.databases.has(DATABASE + 'rows-1-old'));
        await store.append(rows(3, 5));
        await settle(50);
        assert.equal(await store.count(), 5, 'the refused write went through once there was room');

        state.refusals = 5;
        await store.append(rows(5, 8));
        await settle(200);
        await assert.rejects(store.append(rows(8, 9)), (error) => error.quota === true);
        assert.equal(await store.keepWritten(), 5, 'the rows written stay; those that did not fit go');
        state.refusals = 0;
        await store.append(rows(5, 6));
        await settle(50);
        assert.equal(await store.count(), 6, 'and the store takes rows again');
        await store.dispose();
    });
